function reverseInventory(inventory) {
  const reversed = [];
  for (let i = inventory.length - 1; i > -1; i--) {
    reversed.push(inventory[i]);
  }
  return reversed;
}

function lowestHealth(healthValues) {
  let lowest = healthValues[0];
  for (let i = 0; i < healthValues.length; i++) {
    if (healthValues[i] < lowest) {
      lowest = healthValues[i];
    }
  }
  return lowest;
}

function damageRange(enemyDamages) {
  let highestDamage = enemyDamages[0];
  let lowestDamage = enemyDamages[0];
  for (let i = 0; i < enemyDamages.length; i++) {
    if (enemyDamages[i] > highestDamage) {
      highestDamage = enemyDamages[i];
    }
    if (enemyDamages[i] < lowestDamage) {
      lowestDamage = enemyDamages[i];
    }
  }
  return highestDamage - lowestDamage;
}

function hasItem(inventory, itemId) {
  for (let i = 0; i < inventory.length; i++) {
    if (inventory[i] === itemId) {
      return true;
    }
  }
  return false;
}

function averageDamage(damageHits) {
  let totalDamage = 0;
  if (damageHits.length === 0) {
    return totalDamage;
  }
  for (let i = 0; i < damageHits.length; i++) {
    totalDamage += damageHits[i];
  }
  return totalDamage / damageHits.length;
}

